from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict(patient, doctor, start, end, cancelled)
        self._next_id = 1

    def _is_cancelled(self, appt) -> bool:
        return appt["cancelled"]

    def _upcoming(self, appt, now: datetime) -> bool:
        # An appointment is "upcoming" if it hasn't finished yet (and wasn't effectively cancelled)
        if appt["cancelled"]:
            return False
        return appt["end"] > now

    def _slot_blocks(self, appt, now: datetime) -> bool:
        """Whether this appointment currently occupies the doctor's time."""
        if appt["cancelled"]:
            # Cancelled less than 24h before start => slot stays blocked
            if appt["cancel_time"] is not None and appt["start"] - appt["cancel_time"] < timedelta(hours=24):
                # Slot remains blocked only if appointment is still in the future relative to now?
                # Requirement 3: cancelling less than 24h before start does not free the slot.
                return appt["end"] > now
            return False
        return appt["end"] > now

    @staticmethod
    def _overlaps(start1: datetime, end1: datetime, start2: datetime, end2: datetime) -> bool:
        # Touching intervals do not overlap
        return start1 < end2 and start2 < end1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment that starts in the past.")
        if end <= start:
            raise ValueError("Appointment end must be after start.")

        # Requirement 1: patient can have at most one upcoming appointment
        for appt in self._appointments.values():
            if appt["patient"] == patient and self._upcoming(appt, now):
                raise ValueError(
                    "Patient already has an upcoming appointment."
                )

        # Requirement 5: cannot overlap another appointment of same doctor
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not self._slot_blocks(appt, now):
                continue
            if self._overlaps(start, end, appt["start"], appt["end"]):
                raise ValueError("Doctor is not available during that time.")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "id": appt_id,
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "cancel_time": None,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise KeyError("Unknown appointment id.")
        appt = self._appointments[appointment_id]
        if appt["cancelled"]:
            return
        appt["cancelled"] = True
        appt["cancel_time"] = now

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if end <= start:
            return False
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            # Use a permissive "now" for slot blocking: if cancelled and >=24h before, freed
            if appt["cancelled"]:
                if appt["cancel_time"] is not None and appt["start"] - appt["cancel_time"] < timedelta(hours=24):
                    # still blocked
                    pass
                else:
                    continue
            if self._overlaps(start, end, appt["start"], appt["end"]):
                return False
        return True

    def appointments_of(self, doctor: str) -> list[dict]:
        result = [
            {
                "id": appt["id"],
                "patient": appt["patient"],
                "start": appt["start"],
                "end": appt["end"],
            }
            for appt in self._appointments.values()
            if appt["doctor"] == doctor
        ]
        result.sort(key=lambda a: a["start"])
        return result
